function longestWithin(nums, limit) {
  let left = 0, total = 0, best = 0 //@init
  for (let right = 0; right < nums.length; right++) { //@grow
    total += nums[right] //@add
    while (total > limit) { //@check
      total -= nums[left]; left++ //@shrink
    }
    best = Math.max(best, right - left + 1) //@best
  }
  return best //@done
}

