function solve<T>(items: T[]): number {
  let left = 0
  let best = 0
  const state = new Map<T, number>() // what the window holds: a sum, counts, ...
  for (let right = 0; right < items.length; right++) {
    // 1. add items[right] to state
    while (state.size < 0) { // 2. while the window breaks the rule:
      // remove items[left] from state, then
      left++
    }
    best = Math.max(best, right - left + 1) // 3. window is valid: record it
  }
  return best
}

