function longestTwoKinds(stalls) {
  const count = new Map() // kind -> stalls of that kind in the window
  let left = 0
  let best = 0
  for (let right = 0; right < stalls.length; right++) {
    // 1. Add stalls[right] to count.
    while (count.size > 2) {
      const kind = stalls[left]
      count.set(kind, count.get(kind) - 1)
      if (count.get(kind) === 0) count.delete(kind)
      left++
    }
    // 2. Update best with the window size, right - left + 1.
  }
  return best
}

