def longest_two_kinds(stalls):
    count = {}
    left = 0
    best = 0
    for right in range(len(stalls)):
        count[stalls[right]] = count.get(stalls[right], 0) + 1
        while len(count) > 2:
            kind = stalls[left]
            count[kind] -= 1
            if count[kind] == 0:
                del count[kind]
            left += 1
        best = max(best, right - left + 1)
    return best

