function longestTwoKinds(stalls: string): number {
  const count = new Map<string, number>()
  let left = 0
  let best = 0
  for (let right = 0; right < stalls.length; right++) {
    count.set(stalls[right], (count.get(stalls[right]) ?? 0) + 1)
    while (count.size > 2) {
      const kind = stalls[left]
      count.set(kind, count.get(kind)! - 1)
      if (count.get(kind) === 0) count.delete(kind)
      left++
    }
    best = Math.max(best, right - left + 1)
  }
  return best
}
